import numpy as np

def construct():
    # Construct the [17, 8, 6] code by shortening the [18, 9, 6] extended quadratic residue code.
    # The [17, 9, 5] QR code is generated by a matrix G.
    # We keep only codewords with even weight (parity bit 0 in the extension).
    
    n = 17
    k = 9
    
    # Quadratic residues modulo 17 (excluding 0)
    residues = set((i * i) % n for i in range(1, n))
    
    # Generator matrix for the [17, 9, 5] QR code
    G = np.zeros((k, n), dtype=np.int8)
    G[0, :] = 1
    for i in range(1, k):
        for j in range(n):
            if (j - i) % n in residues:
                G[i, j] = 1
    
    # Compute the row-reduced echelon form of G over GF(2) to get a basis
    # This ensures we generate independent codewords and avoid duplicates
    def rref_gf2(mat):
        m, n = mat.shape
        rank = 0
        mat = mat.copy()
        for col in range(n):
            if rank == m:
                break
            pivot = None
            for row in range(rank, m):
                if mat[row, col] == 1:
                    pivot = row
                    break
            if pivot is None:
                continue
            mat[rank], mat[pivot] = mat[pivot].copy(), mat[rank].copy()
            for row in range(m):
                if row != rank and mat[row, col] == 1:
                    mat[row] = (mat[row] + mat[rank]) % 2
            rank += 1
        return mat[:rank, :]

    basis = rref_gf2(G)
    r = basis.shape[0]
    
    # Generate all 2^r possible codewords from the basis
    if r == 0:
        return []
        
    masks = np.array([(m >> i) & 1 for i in range(r) for m in range(1 << r)]).reshape(-1, r)
    
    # Compute codewords: C = masks @ basis % 2
    C = (masks @ basis) % 2
    
    # Filter for even weight
    weights = C.sum(axis=1)
    even_mask = (weights % 2 == 0)
    
    # Convert binary vectors to integers
    powers = np.array([1 << j for j in range(n)], dtype=np.int64)
    words = C[even_mask] @ powers
    
    # Ensure distinct integers (safety net)
    unique_words = set(int(w) for w in words)
    
    return [int(w) for w in unique_words]
